<script setup lang="ts">
import {computed,ref} from 'vue';
import {useRouter} from 'vue-router';
import {ElMessage} from 'element-plus';
import {api,message} from '../api';
import {date,money,ton,label,eventLabel,download} from '../fulfillment';
import {useAuth} from '../stores/auth';
const props=defineProps<{contract:any}>(),router=useRouter(),auth=useAuth(),tab=ref('overview');
const reference=computed(()=>props.contract?.performanceReference),paymentPlans=computed(()=>props.contract?.finance?.paymentPlans||[]),receiptPlans=computed(()=>props.contract?.finance?.receiptPlans||[]),measurements=computed(()=>props.contract?.measurements||[]),paperwork=computed(()=>reference.value?.paperwork||[]),feePlans=computed(()=>reference.value?.feePlans||[]);
const changes=computed(()=>[...(props.contract?.revisions||[]).filter((r:any)=>r.kind!=='ORIGINAL'),...(reference.value?.changes||[])]);
const modeText=(mode:string)=>({ROAD:'公路',WATER:'水运',RAIL:'铁路'} as Record<string,string>)[mode]||mode;
const records=computed(()=>props.contract?.finance?.records||[]),revisions=computed(()=>props.contract?.revisions||[]);
const statusText=(s:string)=>({CONFIRMED:'双方已确认',PENDING:'待对方确认',REJECTED:'已退回',SETTLED:'已结清',PARTIAL:'部分结算',SENT:'已提交对账',CHECKING:'核对中',RECHECK:'待复核',VOID:'已作废',PLANNED:'计划待申请',AWAITING_DOCUMENTS:'待资料核验',AWAITING_RECONCILIATION:'待对账确认',AWAITING_PAYMENT:'待实际收款',PROPOSED:'待双方核实',AWAITING_UPLOAD:'待上传原件',PENDING_CONFIRMATION:'待费用确认',PENDING_VERIFICATION:'待核验'} as Record<string,string>)[s]||label(s);
const timeline=computed(()=>{const c=props.contract;if(!c)return [];if(c.performanceReference)return [...(c.performanceReference.timeline||[])].sort((a,b)=>new Date(b.time).getTime()-new Date(a.time).getTime());const result:any[]=[];
for(const log of c.logs||[])if(log.action!=='sign')result.push({id:'log-'+log.id,time:log.createdAt,title:({submit:'提交合同确认',approve:'承运方确认合同',return:'退回合同修改',withdraw:'撤回合同',reject:'拒签合同'} as Record<string,string>)[log.action]||log.action,note:log.userName||'',kind:'contract'});
for(const r of c.revisions)for(const s of r.signatures)result.push({id:s.id,time:s.signedAt,title:`第 ${r.number} 版 · ${label(s.documentType)} · ${label(s.role)}签署`,note:s.signerName+(s.sealUrl?' · 企业签章':' · 签署记录待核验'),kind:'contract'});
for(const task of c.performance?.tasks||[]){for(const e of (task.events||[]).map((event:any)=>{let payload:any={};try{payload=JSON.parse(event.payload||'{}');}catch{}return {...payload,...event};}))if(e.type!=='POSITION')result.push({id:e.id,time:e.createdAt,title:`第 ${task.segment} 段 · ${eventLabel(e.type)}`,note:[task.businessNo,e.note,e.quantityKg?ton(e.quantityKg):''].filter(Boolean).join(' · '),kind:'transport'});for(const i of task.issues||[])result.push({id:i.id,time:i.createdAt,title:'运输异常 · '+(i.status==='OPEN'?'待处理':'已处理'),note:i.description+(i.resolution?'；'+i.resolution:''),kind:'issue'});}
for(const r of records.value){result.push({id:r.id,time:r.createdAt,title:(r.direction==='PAYMENT'?'登记付款':'登记收款')+' · '+money(r.amountCents),note:r.billNo+' · '+statusText(r.status),kind:'finance'});if(r.confirmedAt)result.push({id:r.id+'-confirmed',time:r.confirmedAt,title:r.status==='CONFIRMED'?'双方确认收付款':'结算记录退回',note:r.response,kind:'finance'});}
return result.sort((a,b)=>new Date(b.time).getTime()-new Date(a.time).getTime());});
const attachments=computed(()=>[...(props.contract?.performance?.tasks||[]).flatMap((t:any)=>(t.evidence||[]).map((f:any)=>({...f,source:`第 ${t.segment} 段运输凭证`,url:`/fulfillment/evidence/${f.id}`,allowed:auth.can('service:read')}))),...(props.contract?.finance?.bills||[]).flatMap((b:any)=>(b.evidence||[]).map((f:any)=>({...f,source:b.businessNo+' · 财务凭证',url:`/billing/evidence/${f.id}`,allowed:auth.can('billing:read')})))]);
async function evidence(f:any){try{const r=await api.get(f.url,{responseType:'blob'});download(r.data,f.name,r.data.type);}catch(e){ElMessage.error(message(e));}}
function billing(id:string){router.push('/billing/reconciliations?id='+id);}
</script>
<template><p v-if="reference" class="tab-note">履约资料待核验 · 付款、收款按计划展示，原始凭证待上传</p><div class="performance-metrics"><div><span>合同运输总价</span><strong>{{money(contract.totalCents)}}</strong></div><div><span>已确认费用 / 已结算</span><strong>{{money(contract.finance.confirmedCents)}} / {{money(contract.finance.settledCents)}}</strong></div><div><span>末段交付量 / 合同量</span><strong>{{ton(contract.progress.completed)}} / {{ton(contract.quantityKg)}}</strong></div></div><el-tabs v-model="tab" class="performance-tabs"><el-tab-pane label="履约过程" name="overview"><div class="performance-progress"><div><strong>运输履约</strong><span>{{({WAITING:'待履行',IN_PROGRESS:'履行中',COMPLETED:'履行完成',TERMINATED:'已终止'} as any)[contract.progress.performanceStatus]}}</span><el-progress :percentage="Math.min(100,Math.round(contract.progress.completed/contract.quantityKg*100))"/></div><div><strong>付款进度</strong><span>{{money(contract.finance.unsettledCents)}} 待结算</span><el-progress :percentage="contract.progress.paymentPercent" color="#cb4850"/></div></div><el-alert v-if="contract.progress.issues" :title="`存在 ${contract.progress.issues} 项待处理运输异常`" type="warning" :closable="false"/><div class="timeline-heading"><h3>履约记录</h3><el-button v-if="auth.can('service:read')" link type="primary" @click="router.push('/services')">查看运输跟踪</el-button></div><el-timeline v-if="timeline.length" class="performance-timeline"><el-timeline-item v-for="item in timeline" :key="item.id" :timestamp="date(item.time)" placement="top" :color="item.kind==='finance'?'#ce5057':item.kind==='issue'?'#e7a546':'#a3acb8'"><strong>{{item.title}}</strong><p>{{item.note}}</p></el-timeline-item></el-timeline><el-empty v-else description="暂无履约记录"/></el-tab-pane><el-tab-pane label="付款信息" name="payments"><template v-if="paymentPlans.length"><h3 class="file-heading">合同付款计划</h3><el-table :data="paymentPlans"><el-table-column prop="name" label="付款节点" width="145"/><el-table-column label="计划金额" width="145"><template #default="{row}">{{money(row.amountCents)}}<small class="cell-note">{{row.ratio}}% · 尚未登记付款</small></template></el-table-column><el-table-column label="预计申请时间" width="170"><template #default="{row}">{{date(row.plannedAt)}}</template></el-table-column><el-table-column prop="condition" label="申请条件" min-width="250"/><el-table-column label="计划状态" width="145"><template #default="{row}"><el-tag type="info">{{statusText(row.status)}}</el-tag></template></el-table-column></el-table><h3 class="file-heading">实际付款登记</h3></template><p class="tab-note">付款方向：{{contract.snapshot.trader.name}} → {{contract.snapshot.carrier.name}}</p><el-table :data="records" empty-text="暂无付款登记，请在对账结算中登记凭证"><el-table-column prop="billNo" label="关联账单" min-width="170"/><el-table-column label="付款金额" width="135"><template #default="{row}">{{money(row.amountCents)}}</template></el-table-column><el-table-column prop="method" label="付款方式" min-width="120"/><el-table-column label="实际付款时间" width="170"><template #default="{row}">{{date(row.actualAt)}}</template></el-table-column><el-table-column label="状态" width="125"><template #default="{row}"><el-tag :type="row.status==='CONFIRMED'?'success':row.status==='REJECTED'?'danger':'warning'">{{statusText(row.status)}}</el-tag></template></el-table-column><el-table-column prop="note" label="说明" min-width="160"/></el-table></el-tab-pane><el-tab-pane label="收款信息" name="receipts"><template v-if="receiptPlans.length"><h3 class="file-heading">收款跟进计划</h3><el-table :data="receiptPlans"><el-table-column prop="name" label="收款节点" width="150"/><el-table-column prop="counterparty" label="付款企业" min-width="220"/><el-table-column label="计划金额" width="145"><template #default="{row}">{{money(row.amountCents)}}</template></el-table-column><el-table-column label="预计收款时间" width="175"><template #default="{row}">{{date(row.plannedAt)}}</template></el-table-column><el-table-column label="收款状态" width="135"><template #default="{row}"><el-tag type="info">{{statusText(row.status)}}</el-tag></template></el-table-column></el-table><h3 class="file-heading">实际收款确认</h3></template><p class="tab-note">收款企业：{{contract.snapshot.carrier.name}} · 已确认结算 {{money(contract.finance.settledCents)}}</p><el-table :data="records" empty-text="暂无收款信息"><el-table-column prop="settlementNo" label="结算编号" min-width="170"/><el-table-column label="金额" width="130"><template #default="{row}">{{money(row.amountCents)}}</template></el-table-column><el-table-column label="收款确认时间" width="180"><template #default="{row}">{{row.status==='CONFIRMED'?date(row.confirmedAt):'—'}}</template></el-table-column><el-table-column label="确认结果" width="150"><template #default="{row}"><el-tag :type="row.status==='CONFIRMED'?'success':'info'">{{statusText(row.status)}}</el-tag></template></el-table-column><el-table-column prop="response" label="确认说明" min-width="180"/></el-table></el-tab-pane><el-tab-pane label="变更信息" name="changes"><el-table :data="changes" empty-text="暂无合同变更或终止协议"><el-table-column label="协议 / 版本" width="160"><template #default="{row}">{{label(row.kind)}} · V{{row.number}}</template></el-table-column><el-table-column prop="reason" label="变更原因" min-width="190"/><el-table-column label="生效状态" width="150"><template #default="{row}"><el-tag>{{statusText(row.status)}}</el-tag></template></el-table-column><el-table-column label="调整事项" min-width="230"><template #default="{row}">{{row.after||row.reason}}</template></el-table-column><el-table-column label="结算约定" min-width="230"><template #default="{row}">{{row.terms?.settlement||row.settlement}}</template></el-table-column><el-table-column label="发起时间" width="175"><template #default="{row}">{{date(row.createdAt)}}</template></el-table-column></el-table></el-tab-pane><el-tab-pane label="计量回传" name="measurements"><p class="tab-note">按港站回传整理净重及箱号，原始过磅、交接资料待核验。</p><el-table :data="measurements" max-height="430" empty-text="尚未收到港站计量资料"><el-table-column prop="taskNo" label="任务编号" min-width="185"/><el-table-column prop="resource" label="车辆 / 运输资源" min-width="160"/><el-table-column label="毛重 / 皮重" min-width="150"><template #default="{row}">{{row.grossKg?ton(row.grossKg):'—'}} / {{row.tareKg?ton(row.tareKg):'—'}}</template></el-table-column><el-table-column label="净重" width="115"><template #default="{row}">{{ton(row.quantityKg)}}</template></el-table-column><el-table-column label="计量编号 / 箱号" min-width="210"><template #default="{row}">{{row.weightTicketNo||'—'}}<small class="cell-note">{{row.containers.map((c:any)=>c.boxNo).join('、')}}</small></template></el-table-column><el-table-column label="回传时间" width="175"><template #default="{row}">{{date(row.receivedAt)}}</template></el-table-column><el-table-column label="核验状态" width="105"><template #default="{row}"><el-tag type="info">{{row.verification==='PENDING_VERIFICATION'?'待核验':'已回传'}}</el-tag></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="费用明细" name="fees"><p class="tab-note">按合同参考金额和阶段作业整理，其他费用须补充业务说明及凭证后确认。</p><el-table :data="feePlans.length?feePlans:contract.performance?.serviceFees||[]" empty-text="暂无阶段费用资料"><el-table-column prop="name" label="费用项目" min-width="175"/><el-table-column label="费用来源" width="110"><template #default="{row}">{{row.source==='CONTRACT'?'合同费用':'其他费用'}}</template></el-table-column><el-table-column label="参考金额" width="135"><template #default="{row}">{{money(row.amountCents)}}</template></el-table-column><el-table-column prop="description" label="计算及作业说明" min-width="300"/><el-table-column label="核对状态" width="125"><template #default="{row}"><el-tag type="info">{{statusText(row.status||'PENDING_CONFIRMATION')}}</el-tag></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="运输任务" name="transport"><el-table :data="contract.performance?.tasks||[]" empty-text="尚未建立运输任务"><el-table-column prop="businessNo" label="任务编号" min-width="170"/><el-table-column label="区段" width="75"><template #default="{row}">第{{row.segment}}段</template></el-table-column><el-table-column prop="resource" label="运输资源" min-width="180"/><el-table-column label="实际交付数量" width="170"><template #default="{row}">{{row.unloadedKg>0?ton(row.unloadedKg):row.mode==='ROAD'?'待过磅':'待回传'}}</template></el-table-column><el-table-column label="状态" width="140"><template #default="{row}">{{label(row.status)}}</template></el-table-column></el-table></el-tab-pane><el-tab-pane label="合同与凭证" name="files"><h3 class="file-heading">合同关联账单</h3><el-table :data="contract.finance.bills" empty-text="暂无关联账单"><el-table-column prop="businessNo" label="账单编号" min-width="170"/><el-table-column label="账单金额" width="130"><template #default="{row}">{{money(row.totalCents)}}</template></el-table-column><el-table-column label="对账 / 结算状态" min-width="160"><template #default="{row}">{{statusText(row.status)}} / {{row.settlementStatus?statusText(row.settlementStatus):'未进入结算'}}</template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button v-if="auth.can('billing:read')" link type="primary" @click="billing(row.id)">查看账单</el-button></template></el-table-column></el-table><template v-if="paperwork.length"><h3 class="file-heading">归档资料清单</h3><el-table :data="paperwork"><el-table-column prop="name" label="所需资料" min-width="200"/><el-table-column prop="description" label="核验事项" min-width="300"/><el-table-column label="资料状态" width="140"><template #default="{row}"><el-tag type="info">{{statusText(row.status)}}</el-tag></template></el-table-column></el-table></template><h3 class="file-heading">运输与财务凭证</h3><el-table :data="attachments" empty-text="暂无附件凭证"><el-table-column prop="name" label="凭证文件" min-width="220"/><el-table-column prop="source" label="来源" min-width="210"/><el-table-column label="上传时间" width="170"><template #default="{row}">{{date(row.createdAt)}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button v-if="row.allowed" link type="primary" @click="evidence(row)">下载凭证</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></template>
<style scoped>.performance-metrics{display:grid;grid-template-columns:1fr 1.4fr 1fr;background:#f6f7fa;border-radius:7px;margin:12px 0 25px;padding:22px;gap:20px}.performance-metrics span{color:#929ba7;font-size:12px}.performance-metrics strong{display:block;font-size:19px;margin-top:12px;font-variant-numeric:tabular-nums}.performance-tabs{margin-top:20px}.performance-progress{display:grid;grid-template-columns:1fr 1fr;gap:40px;border:1px solid #e6e9ee;padding:24px;border-radius:7px;margin:18px 0 24px}.performance-progress strong{font-size:13px}.performance-progress span{display:block;font-size:12px;color:#8792a1;margin:12px 0}.timeline-heading{display:flex;align-items:center;justify-content:space-between;margin:28px 0}.timeline-heading h3,.file-heading{font-size:14px}.performance-timeline{padding-left:5px}.performance-timeline strong{font-size:13px;font-weight:500}.performance-timeline p{font-size:12px;color:#7e8998;margin-top:9px;line-height:1.8}.tab-note{color:#858f9e;font-size:12px;padding:10px 0 20px}.file-heading{margin:22px 0 15px}@media(max-width:650px){.performance-metrics,.performance-progress{grid-template-columns:1fr;gap:20px}.performance-metrics strong{font-size:16px}}</style>
